CREATE POLICY "anexos leitura propria" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'anexos' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "anexos envio proprio" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'anexos' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "anexos atualizacao propria" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'anexos' AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK (bucket_id = 'anexos' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "anexos remocao propria" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'anexos' AND (storage.foldername(name))[1] = auth.uid()::text);